static uint32_t frame_instruction(uint32_t w){return (w&0x7c000000)==0x14000000?w&0xfc000000:w;}
static int frame_shape(const void* memory,const uint32_t* expected,size_t n){for(size_t i=0;i<n;i++){uint32_t w;memcpy(&w,(const char*)memory+i*4,4);if(frame_instruction(w)!=expected[i])return 0;}return 1;}
